using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;
// Native independent-drop path for normal monsters (FG355).
// Source: data/independent-drops-FG355.dat, generated by local-run/pvf/gen_independent_drops.py.
// Original semantics (rednf killMonsterDropItem + generateIndependentItem, single player):
//   ref.m_rateSlot     = dungeon difficulty      -> rates[difficulty]
//   ref.m_field34      = eraseCnt = monster level -> rangeMin/rangeMax filter
//   ref.m_field3e_byte = party member count = 1   -> expect[0] attempts
//   ref.m_field24 = 0 (random), m_field25 = 0 (no level filter), m_field30 = 0,
//   m_premiumDropRate = 0, m_field3c_byte = 0, m_field3f = 0.
// A record hits when rates[difficulty] > rand(1_000_000); count = min(hits, limit); then either
// one copy of itemIdx per count or `count` cumulative-weight picks over the [list].
// Items not registered in item-metadata are kept in the table with Registered=false so the
// probabilities of the remaining entries do not shift; they simply yield nothing until their
// definition is registered.
class Offline70IndependentDropsFG355{
 internal const string Magic="FG355ID1";internal const int MaximumBytes=16777216;
 internal sealed class Pair{internal uint Item;internal uint Cumulative;internal bool Registered;}
 internal sealed class Entry{internal ushort Monster;internal bool HasPairs;internal uint Value;internal uint[] Rates;internal ushort[] Expect;internal ushort Limit;internal byte RangeMin,RangeMax;internal bool ItemRegistered;internal Pair[] Pairs;}
 static readonly Dictionary<ushort,Entry[]> Table=new Dictionary<ushort,Entry[]>();
 static readonly HashSet<uint> KnownItems=new HashSet<uint>();static readonly HashSet<uint> MissingItems=new HashSet<uint>();
 internal static int Records,UnsupportedItems;
 internal static void Load(string path){
  if(Table.Count!=0)return;byte[] b=File.ReadAllBytes(path);if(b.Length<74||b.Length>MaximumBytes)throw new InvalidDataException("Independent drop catalog size");
  if(Encoding.ASCII.GetString(b,0,8)!=Magic)throw new InvalidDataException("Independent drop catalog magic");
  if(Encoding.ASCII.GetString(b,8,64).ToUpperInvariant()!=Offline70QuestCatalogFG.CurrentPvf)throw new InvalidDataException("Independent drop catalog PVF");
  int count;
  using(BinaryReader r=new BinaryReader(new MemoryStream(b,false),Encoding.ASCII)){
   r.BaseStream.Position=72;count=r.ReadUInt16();if(count<1||count>8192)throw new InvalidDataException("Independent drop record count");
   Dictionary<ushort,List<Entry>> lists=new Dictionary<ushort,List<Entry>>();
   for(int i=0;i<count;i++){
    ushort monster=r.ReadUInt16();byte hasPairs=r.ReadByte(),reserved=r.ReadByte();if(reserved!=0||monster==0)throw new InvalidDataException("Independent drop record header");
    uint value=r.ReadUInt32();uint[] rates=new uint[5];for(int k=0;k<5;k++)rates[k]=r.ReadUInt32();
    ushort[] expect=new ushort[4];for(int k=0;k<4;k++)expect[k]=r.ReadUInt16();
    ushort limit=r.ReadUInt16();byte rangeMin=r.ReadByte(),rangeMax=r.ReadByte();ushort pairCount=r.ReadUInt16();
    if(limit>255||pairCount>4096||rangeMax!=0&&rangeMin>rangeMax)throw new InvalidDataException("Independent drop bounds");
    foreach(ushort attempts in expect)if(attempts>255)throw new InvalidDataException("Independent drop attempt bound");
    if(hasPairs==0){if(value<=2||pairCount!=0)throw new InvalidDataException("Independent drop single item");}
    else if(hasPairs==1){if(value==0||pairCount==0)throw new InvalidDataException("Independent drop pair list");}
    else throw new InvalidDataException("Independent drop pair flag");
    Pair[] pairs=pairCount==0?null:new Pair[pairCount];uint previous=0;
    for(int k=0;k<pairCount;k++){
     uint item=r.ReadUInt32(),cumulative=r.ReadUInt32();if(item<=2||cumulative<=previous)throw new InvalidDataException("Independent drop pair row");
     Pair p=new Pair{Item=item,Cumulative=cumulative,Registered=Known(item)};pairs[k]=p;previous=cumulative;
    }
    if(hasPairs==1&&previous!=value)throw new InvalidDataException("Independent drop main rate");
    Entry e=new Entry{Monster=monster,HasPairs=hasPairs==1,Value=value,Rates=rates,Expect=expect,Limit=limit,RangeMin=rangeMin,RangeMax=rangeMax,Pairs=pairs,ItemRegistered=hasPairs==0&&Known(value)};
    List<Entry> rows;if(!lists.TryGetValue(monster,out rows)){rows=new List<Entry>();lists.Add(monster,rows);}
    rows.Add(e);
   }
   if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Independent drop catalog trailing bytes");
   foreach(KeyValuePair<ushort,List<Entry>> pair in lists)Table.Add(pair.Key,pair.Value.ToArray());
  }
  Records=count;UnsupportedItems=MissingItems.Count;
 }
 static bool Known(uint item){
  if(KnownItems.Contains(item))return true;
  if(MissingItems.Contains(item))return false;
  try{Offline70Economy.Definition(item);KnownItems.Add(item);return true;}catch(InvalidDataException){MissingItems.Add(item);return false;}
 }
 internal static bool Has(ushort monster){return Table.ContainsKey(monster);}
 internal static Entry[] Entries(ushort monster){Entry[] rows;return Table.TryGetValue(monster,out rows)?rows:new Entry[0];}
 internal static ushort[] Monsters(){ushort[] rows=new ushort[Table.Count];Table.Keys.CopyTo(rows,0);Array.Sort(rows);return rows;}
 internal static bool Registered(uint item){return KnownItems.Contains(item);}
 internal static bool Unsupported(uint item){return MissingItems.Contains(item);}
 internal static uint Draw(string receipt,string purpose,uint maximum){
  if(String.IsNullOrEmpty(receipt)||receipt.Length>200||String.IsNullOrEmpty(purpose)||purpose.Length>80||maximum==0||maximum>1000000000U)throw new InvalidDataException("Independent drop draw bounds");
  ulong span=maximum,limit=4294967296UL/span*span;
  for(int attempt=0;attempt<1024;attempt++){
   byte[] digest;using(SHA256 h=SHA256.Create())digest=h.ComputeHash(Encoding.UTF8.GetBytes(receipt+"|fg355|"+purpose+"|"+attempt));
   uint v=BitConverter.ToUInt32(digest,0);if(v<limit)return (uint)(v%span);
  }
  throw new InvalidDataException("Independent drop random rejection limit");
 }
 internal static List<Offline70FloorDropsFG119.Reward> Plan(ushort monster,byte difficulty,byte level,string receipt){
  return Plan(monster,difficulty,level,receipt,delegate(string purpose,uint maximum){return Draw(receipt,purpose,maximum);});
 }
 internal static List<Offline70FloorDropsFG119.Reward> Plan(ushort monster,byte difficulty,byte level,string receipt,Func<string,uint,uint> draw){
  if(difficulty>4||draw==null)throw new InvalidDataException("Independent drop context");
  List<Offline70FloorDropsFG119.Reward> rewards=new List<Offline70FloorDropsFG119.Reward>();Entry[] rows;if(!Table.TryGetValue(monster,out rows))return rewards;
  for(int index=0;index<rows.Length;index++){
   Entry e=rows[index];
   if((e.RangeMin!=0||e.RangeMax!=0)&&(e.RangeMin>level||e.RangeMax<level))continue;
   uint rate=e.Rates[difficulty];int hits=0;
   for(int attempt=0;attempt<e.Expect[0];attempt++)if(rate>draw("r"+index+":a"+attempt+":chance",1000000U))hits++;
   int count=Math.Min(hits,(int)e.Limit);if(count<=0)continue;
   if(e.HasPairs){
    for(int k=0;k<count;k++){
     uint roll=draw("r"+index+":i"+k+":pick",e.Value);Pair chosen=null;foreach(Pair p in e.Pairs)if(p.Cumulative>roll){chosen=p;break;}
     if(chosen==null)throw new InvalidDataException("Independent drop pair selection");
     if(chosen.Registered)rewards.Add(new Offline70FloorDropsFG119.Reward{Item=chosen.Item,Quantity=1,Source="independent-original355"});
    }
   }else if(e.ItemRegistered)for(int k=0;k<count;k++)rewards.Add(new Offline70FloorDropsFG119.Reward{Item=e.Value,Quantity=1,Source="independent-original355"});
  }
  return rewards;
 }
 internal static int Append(List<Offline70FloorDropsFG119.Reward> rewards,ushort monster,byte difficulty,byte level,string receipt){
  return Append(rewards,Plan(monster,difficulty,level,receipt));
 }
 internal static int Append(List<Offline70FloorDropsFG119.Reward> rewards,List<Offline70FloorDropsFG119.Reward> planned){
  if(rewards==null||planned==null)throw new InvalidDataException("Independent drop rewards");int added=0;
  foreach(Offline70FloorDropsFG119.Reward reward in planned){
   if(rewards.Count>=Offline70FloorDropsFG119.MaximumRows)break;
   rewards.Add(reward);added++;
  }
  return added;
 }
}
